    ctx.beginPath();
    ctx.moveTo(cx + Math.cos(angle) * r * 1.25, cy + Math.sin(angle) * r * 1.25);
    ctx.lineTo(cx + Math.cos(angle) * r * 1.7, cy + Math.sin(angle) * r * 1.7);
    ctx.stroke();
