  ctx.restore();

  ctx.save();
  ctx.fillStyle = 'rgba(232, 196, 106, 0.9)';
  ctx.textAlign = 'center';
  ctx.textBaseline = 'middle';
  ctx.font = `600 ${Math.max(9, Math.min(rect.w, rect.h) * 0.055)}px "Segoe UI", system-ui, sans-serif`;
