// The Vice Horizon backdrop: a magenta-to-orange sky, a slitted sun, a dark
// skyline and two palms, all built from gradients and canvas paths.

export const PALETTE = {
  ink: '#07030f',
  navyTop: '#0a0d22',
  navyBottom: '#161d45',
  gold: '#e8c46a',
  goldBright: '#ffe9a8',
  magenta: '#ff3d93',
  orange: '#ff8a3d',
  white: '#ffffff',
