  const c = canvas.getContext('2d');
  const image = c.createImageData(size, size);
  const rand = seedRandom(2026);
  for (let i = 0; i < image.data.length; i += 4) {
    const v = Math.floor(rand() * 255);
    image.data[i] = v;
    image.data[i + 1] = v;
    image.data[i + 2] = v;
    image.data[i + 3] = Math.floor(rand() * 60);
